import androidx.compose.material.icons.Icons
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * The 24 Material icons LNXV uses that live in material-icons-extended (a ~10 MB dependency we no longer ship).
 * Path data is copied from google/material-design-icons (Apache-2.0), baseline 24px "filled" variants.
 * Declared as extensions on [Icons.Filled] so existing `Icons.Default.X` call sites keep working
 * (only the import changes to this package).
 */
private fun icon(name: String, vararg paths: String): ImageVector {
    val b = ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
    paths.forEach { d ->
        runCatching { PathParser().parsePathString(d).toNodes() }.getOrNull()?.let { nodes ->
            b.addPath(pathData = nodes, fill = SolidColor(Color.Black))
        }
    }
    return b.build()
}

